#[derive(Clone, Copy, Debug)]
enum TimerSneakStep {
    Start,
    OnTouch,
    OnInit,
    OnEnter,
    OnTimer180000,
    OnTimer190000,
}

fn timer_sneak_run(ctx: &Ctx, mut step: TimerSneakStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            TimerSneakStep::Start => {
                step = TimerSneakStep::OnTouch;
                continue 'machine;
            }
            TimerSneakStep::OnTouch => {
                ctx.call(Function::Warp, vec![Val::from("lhz_in01"), Val::from(191), Val::from(49)])?;
                return Err(Stop::End);
            }
            TimerSneakStep::OnInit => {
                ctx.call(Function::DisableNpc, vec![Val::from("Timer_Sneak")])?;
                return Err(Stop::End);
            }
            TimerSneakStep::OnEnter => {
                ctx.call(Function::StopNpcTimer, vec![])?;
                ctx.call(Function::InitNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            TimerSneakStep::OnTimer180000 => {
                ctx.call(Function::EnableNpc, vec![Val::from("Timer_Sneak")])?;
                return Err(Stop::End);
            }
            TimerSneakStep::OnTimer190000 => {
                ctx.call(Function::StopNpcTimer, vec![])?;
                ctx.call(Function::DisableNpc, vec![Val::from("Timer_Sneak")])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn timer_sneak(ctx: &Ctx) -> Script {
    timer_sneak_run(ctx, TimerSneakStep::Start, Vec::new()).map(|_| ())
}

