#[derive(Clone, Copy, Debug)]
enum PackidentityStep {
    Start,
    OnInit,
    OnEnter,
    OnTouch,
    OnTimer120000,
}

fn packidentity_run(ctx: &Ctx, mut step: PackidentityStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            PackidentityStep::Start => {
                return Err(Stop::End);
            }
            PackidentityStep::OnInit => {
                ctx.call(Function::DisableNpc, vec![Val::from("#packidentity")])?;
                return Err(Stop::End);
            }
            PackidentityStep::OnEnter => {
                ctx.call(Function::InitNpcTimer, vec![])?;
                ctx.call(Function::EnableNpc, vec![Val::from("#packidentity")])?;
                return Err(Stop::End);
            }
            PackidentityStep::OnTouch => {
                if ctx.var("lhz_rekenber").get()? == 19 {
                    ctx.lines(args![
                        "^3355FFYou peek through the",
                        "slit in the wrapping",
                        "that is covering one",
                        "of the packages.^000000"
                    ])?;
                    ctx.next()?;
                    ctx.lines_as(
                        ctx.call(Function::StrCharInfo, vec![Val::from(0)])?,
                        args![
                            "Oh... my God!",
                            "These are... These are",
                            "weapons of mass destruction.",
                            "There's even parts for assembling guardians, the kinds that usually",
                            "defend those Guild Castles..."
                        ],
                    )?;
                    ctx.close_window()?;
                    ctx.call(Function::DoNpcEvent, vec![Val::from("Man#Lyozien::OnEnter")])?;
                    ctx.call(Function::DoNpcEvent, vec![Val::from("#packidentity::OnInit")])?;
                    ctx.call(Function::StopNpcTimer, vec![])?;
                    return Err(Stop::End);
                }
                step = PackidentityStep::OnTimer120000;
                continue 'machine;
            }
            PackidentityStep::OnTimer120000 => {
                ctx.call(Function::DoNpcEvent, vec![Val::from("Man#Lyozien::OnEnter")])?;
                ctx.call(Function::DoNpcEvent, vec![Val::from("#packidentity::OnInit")])?;
                ctx.call(Function::StopNpcTimer, vec![])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn packidentity(ctx: &Ctx) -> Script {
    packidentity_run(ctx, PackidentityStep::Start, Vec::new()).map(|_| ())
}

pub fn packidentity_oninit(ctx: &Ctx) -> Script {
    packidentity_run(ctx, PackidentityStep::OnInit, Vec::new()).map(|_| ())
}

pub fn packidentity_onenter(ctx: &Ctx) -> Script {
    packidentity_run(ctx, PackidentityStep::OnEnter, Vec::new()).map(|_| ())
}

pub fn packidentity_ontouch(ctx: &Ctx) -> Script {
    packidentity_run(ctx, PackidentityStep::OnTouch, Vec::new()).map(|_| ())
}

pub fn packidentity_ontimer120000(ctx: &Ctx) -> Script {
    packidentity_run(ctx, PackidentityStep::OnTimer120000, Vec::new()).map(|_| ())
}

